create extension if not exists pgcrypto;
create or replace function public.set_updated_at() returns trigger language plpgsql security invoker set search_path='' as $$ begin new.updated_at=now(); return new; end; $$;
create table public.categories(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,parent_id uuid references public.categories(id),sort_order integer not null default 0,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.job_descriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,company text not null check(char_length(company) between 1 and 200),job_title text not null check(char_length(job_title) between 1 and 200),category_id uuid not null references public.categories(id),subcategory_id uuid references public.categories(id),seniority text not null default 'UNSPECIFIED' check(seniority in('INTERN','ENTRY','JUNIOR','MID','SENIOR','LEAD','PRINCIPAL','MANAGER','DIRECTOR','EXECUTIVE','UNSPECIFIED')),source_site text not null default '',source_url text not null default '' check(char_length(source_url)<=4000),normalized_source_url text,captured_at_client timestamptz null,description_text text not null check(char_length(description_text) between 100 and 200000),detected_skills text[] not null default '{}',capture_method text not null default 'manual' check(capture_method in('json-ld','site-specific','dom','selected-text','manual')),extraction_confidence text not null default 'low' check(extraction_confidence in('high','medium','low')),status text not null default 'ACTIVE' check(status in('ACTIVE','ARCHIVED')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index job_descriptions_user_normalized_url_key on public.job_descriptions(user_id,normalized_source_url) where normalized_source_url is not null and normalized_source_url<>'';create index job_descriptions_user_id_idx on public.job_descriptions(user_id);
create table public.resumes(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,candidate_name text not null check(char_length(candidate_name) between 1 and 200),resume_name text not null check(char_length(resume_name) between 1 and 200),primary_category_id uuid not null references public.categories(id),subcategory_id uuid references public.categories(id),seniority text not null default 'UNSPECIFIED' check(seniority in('INTERN','ENTRY','JUNIOR','MID','SENIOR','LEAD','PRINCIPAL','MANAGER','DIRECTOR','EXECUTIVE','UNSPECIFIED')),skills text[] not null default '{}',industries text[] not null default '{}',resume_text text not null check(char_length(resume_text) between 100 and 300000),storage_bucket text not null default 'original-resumes' check(storage_bucket='original-resumes'),storage_path text not null,original_filename text not null,mime_type text not null check(mime_type in('application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','text/plain')),file_size_bytes bigint not null check(file_size_bytes between 1 and 5242880),file_sha256 text not null check(file_sha256~'^[0-9a-f]{64}$'),status text not null default 'ACTIVE' check(status in('ACTIVE','ARCHIVED')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(storage_path like user_id::text||'/%'));
create index resumes_user_status_idx on public.resumes(user_id,status);create index resumes_user_category_status_idx on public.resumes(user_id,primary_category_id,status);create index resumes_user_created_idx on public.resumes(user_id,created_at desc);
create table public.tailoring_jobs(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,job_description_id uuid not null references public.job_descriptions(id) on delete cascade,resume_id uuid not null references public.resumes(id) on delete restrict,match_score numeric(5,2) not null check(match_score between 0 and 100),match_details jsonb not null default '{}'::jsonb,status text not null default 'PENDING' check(status in('PENDING','PROCESSING','NEEDS_REVIEW','APPROVED','REJECTED','COMPLETED','FAILED','CANCELLED')),source_resume_path text not null,tailored_resume_path text,review_notes text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),started_at timestamptz,completed_at timestamptz,unique(user_id,job_description_id,resume_id));create index tailoring_jobs_user_id_idx on public.tailoring_jobs(user_id);
create or replace function public.validate_category_relationship() returns trigger language plpgsql security invoker set search_path='' as $$ declare parent uuid; begin if tg_table_name='resumes' then if new.subcategory_id is not null then select parent_id into parent from public.categories where id=new.subcategory_id and active=true;if parent is distinct from new.primary_category_id then raise exception 'Invalid subcategory relationship' using errcode='23514';end if;end if;else if new.subcategory_id is not null then select parent_id into parent from public.categories where id=new.subcategory_id and active=true;if parent is distinct from new.category_id then raise exception 'Invalid subcategory relationship' using errcode='23514';end if;end if;end if;return new;end;$$;
create or replace function public.validate_tailoring_job() returns trigger language plpgsql security invoker set search_path='' as $$ declare resume_owner uuid;jd_owner uuid;resume_path text;resume_status text;begin select user_id into jd_owner from public.job_descriptions where id=new.job_description_id;select user_id,storage_path,status into resume_owner,resume_path,resume_status from public.resumes where id=new.resume_id;if jd_owner is distinct from new.user_id or resume_owner is distinct from new.user_id then raise exception 'Referenced records must belong to user' using errcode='42501';end if;if tg_op='INSERT' and (resume_path is distinct from new.source_resume_path or resume_status<>'ACTIVE') then raise exception 'Source resume must be active and path must match' using errcode='23514';end if;return new;end;$$;
create trigger categories_updated before update on public.categories for each row execute function public.set_updated_at();create trigger jobs_updated before update on public.job_descriptions for each row execute function public.set_updated_at();create trigger resumes_updated before update on public.resumes for each row execute function public.set_updated_at();create trigger tailoring_updated before update on public.tailoring_jobs for each row execute function public.set_updated_at();create trigger jobs_category before insert or update on public.job_descriptions for each row execute function public.validate_category_relationship();create trigger resumes_category before insert or update on public.resumes for each row execute function public.validate_category_relationship();create trigger tailoring_validate before insert or update on public.tailoring_jobs for each row execute function public.validate_tailoring_job();
